/bin/bash -lc "python - <<'PY'
import numpy as np, mujoco
from sim import Sim
sim=Sim(); m=sim.model; d=sim.data
hand=mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_BODY,'hand')
rng=np.random.default_rng(0)
qmin=m.actuator_ctrlrange[:7,0]; qmax=m.actuator_ctrlrange[:7,1]
targets={'handle':np.array([0.74,-0.02,0.47]),'block_front':np.array([0.63,-0.02,0.44]),'above':np.array([0.7,-0.02,0.6])}
best={k:(1e9,None,None) for k in targets}
for i in range(20000):
    q = qmin + rng.random(7)*(qmax-qmin)
    d.qpos[:7]=q; d.qvel[:]=0; mujoco.mj_forward(m,d)
    pos=d.xpos[hand].copy()
    for k,t in targets.items():
        dist=float(np.linalg.norm(pos-t))
        if dist<best[k][0]:
            best[k]=(dist,q.copy(),pos.copy())
for k,v in best.items():
    print(k,'dist',v[0],'q',v[1],'pos',v[2])
PY"

